#!/usr/bin/env python3
from pathlib import Path
import html,json,re
ROOT=Path(__file__).resolve().parents[1]; OUT=ROOT/'data/research'; PUBLIC=ROOT/'public'

def pct(n,d): return round(100*n/d,1) if d else 0

def main():
    s=json.loads((OUT/'corpus_research_statistics.json').read_text(encoding='utf-8'))
    sem=json.loads((OUT/'diachronic_semantic_context_queue.json').read_text(encoding='utf-8'))['records']
    con=json.loads((OUT/'internal_concordance.json').read_text(encoding='utf-8'))['records']
    de=s['active_articles_by_direction']['DE-RAR']; rar=s['active_articles_by_direction']['RAR-DE']; semc=s['diachronic_semantic_context_signal_counts']; any_internal=semc.get('internal_form_attestation_only',0)+semc.get('internal_reciprocal_documentary_support',0); total=s['diachronic_semantic_context_candidates']; recip=semc.get('internal_reciprocal_documentary_support',0)

    readme=(ROOT/'README.md').read_text(encoding='utf-8')
    badge='  <img src="https://img.shields.io/badge/concordancia%20interna-989-2d6a4f?style=flat-square" alt="989 internal Steffel concordance candidates">\n  <img src="https://img.shields.io/badge/apoyo%20rec%C3%ADproco-337-9a6b1f?style=flat-square" alt="337 reciprocal German documentary support candidates">\n  <img src="https://img.shields.io/badge/diacron%C3%ADa%20candidata-298-7a263a?style=flat-square" alt="298 machine diachronic candidates">\n'
    if 'concordancia%20interna-989' not in readme:
        readme=readme.replace('  <img src="https://img.shields.io/badge/revisi%C3%B3n%20humana-0%2F482-6b7280?style=flat-square" alt="0 of 482 independently human reviewed">\n','  <img src="https://img.shields.io/badge/revisi%C3%B3n%20humana-0%2F482-6b7280?style=flat-square" alt="0 of 482 independently human reviewed">\n'+badge)
    research_section=f'''## Investigación interna de Steffel sin adjudicación humana\n\nLa indisponibilidad temporal de revisión humana no detiene las capas **documentales y computacionales no adjudicativas**. El proyecto explota ahora la estructura bidireccional del propio Steffel sin alterar la transcripción diplomática. En la sección RAR–DE se documentan **{s['rar_de_component_attestations']} componentes**, **{s['rar_de_unique_surface_forms']} formas superficiales** y **{s['rar_de_unique_graphic_keys']} claves gráficas conservadoras únicas**.\n\nLa búsqueda guiada por ese inventario dentro de los artículos DE–RAR produjo **{s['de_rar_inventory_guided_attestations']} atestiguaciones candidatas**, distribuidas en **{s['de_rar_records_with_inventory_guided_attestations']} registros DE–RAR** y **{s['rar_de_records_attested_inside_de_rar']} registros RAR–DE**. De las **{s['internal_concordance_candidates']} relaciones de concordancia interna**, **{s['internal_reciprocal_german_support_candidates']}** tienen además apoyo alemán recíproco entre el encabezado DE–RAR y la glosa local RAR–DE. Esta señal fortalece la trazabilidad documental de la lectura histórica, pero **no constituye identidad semántica ni validación lingüística**.\n\nEn paralelo se conservan **{s['residual_de_rar_span_candidates_low_machine']} segmentos residuales de baja confianza**; no se contabilizan como nuevas palabras rarámuri. El índice histórico separa **{s['explicit_source_variant_groups']} grupos de variantes explícitas impresas** de **{s['normalized_graphic_collision_groups']} colisiones bajo normalización gráfica conservadora**.\n\nLa cola diacrónica de 298 hipótesis incorpora ahora contexto interno de Steffel: **{any_internal}/{total} ({pct(any_internal,total)}%)** tienen alguna atestiguación interna y **{recip}/{total} ({pct(recip,total)}%)** cuentan con apoyo documental recíproco. Son proporciones de cobertura/señal, **no tasas de validación**. La comparación semántica alemán↔español no se automatiza.\n\nArtefactos: `data/research/de_rar_inventory_guided_attestations.*`, `internal_concordance.*`, `historical_variant_index.json`, `diachronic_semantic_context_queue.*`, `graphemic_statistics.json`, `corpus_research_statistics.json` y `RESEARCH_SNAPSHOT.md`.\n\n'''
    if '## Investigación interna de Steffel sin adjudicación humana' not in readme:
        readme=readme.replace('## Frontera documental\n',research_section+'## Frontera documental\n')
    if 'scripts/generate_de_rar_attestations.py' not in readme:
        readme=readme.replace('python3 scripts/generate_human_review_priority.py\npython3 scripts/generate_exports.py\n','python3 scripts/generate_human_review_priority.py\npython3 scripts/generate_exports.py\npython3 scripts/generate_de_rar_attestations.py\npython3 scripts/generate_internal_concordance.py\npython3 scripts/generate_historical_variants.py\npython3 scripts/generate_semantic_context_queue.py\npython3 scripts/generate_graphemic_statistics.py\npython3 scripts/generate_research_statistics.py\npython3 scripts/generate_research_snapshot.py\npython3 scripts/sync_research_metadata.py\n')
    new_next='''## Siguiente etapa operativa\n\nLa **siguiente etapa de validación** continúa siendo la revisión humana independiente de `data/validation/human_review_priority.json`, comenzando por los 46 casos aún irresueltos. Mientras esa adjudicación no esté disponible, el proyecto puede avanzar legítimamente en un carril paralelo de investigación documental: concordancia interna DE–RAR ↔ RAR–DE, estadística grafémica, variantes explícitas, cobertura, empaquetado de contexto diacrónico y mejora de herramientas de consulta.\n\nEstas capas permanecen separadas de la validación. Ningún candidato computacional puede activar `human_verified`, `philologically_verified_by_human`, `linguistically_verified` ni `human_reviewed`. La eventual revisión independiente podrá aceptar, modificar, rechazar o mantener inciertas las relaciones sin borrar la evidencia previa.\n\n'''
    readme=re.sub(r'## Siguiente etapa operativa\n.*?(?=## Identificadores y relación diacrónica)',new_next,readme,flags=re.S)
    readme=readme.replace('El corpus histórico permanece separado de Rarámuri Digital. Las futuras correspondencias Steffel ↔ Rarámuri Digital serán relaciones explícitas con confianza, método y revisión.','El corpus histórico permanece separado de Rarámuri Digital. Existen ya 298 hipótesis diacrónicas de máquina y una cola de contexto documental; todas son relaciones derivadas con método y trazabilidad explícitos y ninguna se promueve a correspondencia validada sin revisión independiente.')
    (ROOT/'README.md').write_text(readme,encoding='utf-8')

    change=(ROOT/'CHANGELOG.md').read_text(encoding='utf-8')
    marker='## Investigación interna — 2026-08-13'
    if marker not in change:
        block=f'''{marker}\n\n- Nueva extracción conservadora DE–RAR guiada por el inventario RAR–DE: {s['de_rar_inventory_guided_attestations']} atestiguaciones candidatas; {s['residual_de_rar_span_candidates_low_machine']} segmentos residuales quedan separados como baja confianza.\n- Concordancia interna Steffel DE–RAR ↔ RAR–DE: {s['internal_concordance_candidates']} relaciones candidatas, {s['internal_reciprocal_german_support_candidates']} con apoyo alemán recíproco.\n- Índice documental de variantes: {s['explicit_source_variant_groups']} grupos explícitos y {s['normalized_graphic_collision_groups']} colisiones gráficas conservadoras.\n- Contexto diacrónico enriquecido para los 298 candidatos: {recip} con apoyo interno recíproco, {semc.get('internal_form_attestation_only',0)} con atestiguación interna no recíproca y {semc.get('cross_corpus_context_only',0)} sólo con contexto entre corpus.\n- Estadística grafémica y corte reproducible en `data/research/`; exportaciones CSV para concordancia y contexto semántico.\n- La revisión humana de relaciones permanece en 0; ninguna señal computacional se interpreta como validación lingüística.\n\n'''
        change=change.replace('# Changelog\n','# Changelog\n\n'+block,1)
    (ROOT/'CHANGELOG.md').write_text(change,encoding='utf-8')

    index=(PUBLIC/'index.html').read_text(encoding='utf-8')
    if 'research.html' not in index:
        index=index.replace('<a href="#consulta">Consulta</a>','<a href="#consulta">Consulta</a><a href="research.html">Investigación</a>',1)
    index=index.replace('Las futuras correspondencias Steffel ↔ Rarámuri Digital serán relaciones explícitas con nivel de certeza, método y revisión, no fusiones automáticas.','El proyecto mantiene 298 hipótesis Steffel ↔ Rarámuri Digital como relaciones derivadas y trazables. La concordancia interna del propio Steffel aporta contexto adicional sin fusionar corpus ni convertir candidatos en equivalencias validadas.')
    if 'id="investigacion"' not in index:
        panel=f'''\n<section class="panel" id="investigacion"><h2>Investigación interna de Steffel</h2><p>La estructura bidireccional del diccionario permite contrastar el propio Steffel consigo mismo. Una búsqueda conservadora guiada por los lemas RAR–DE localizó <strong>{s['de_rar_inventory_guided_attestations']} atestiguaciones candidatas</strong> dentro de artículos DE–RAR y construyó <strong>{s['internal_concordance_candidates']} relaciones internas</strong>; {s['internal_reciprocal_german_support_candidates']} tienen además apoyo alemán recíproco entre encabezado y glosa.</p><div class="pagegrid"><article class="pagecard"><span>{s['rar_de_unique_graphic_keys']}</span><strong>claves RAR–DE únicas</strong><p>Inventario documental bajo normalización gráfica conservadora.</p></article><article class="pagecard"><span>{any_internal}/{total}</span><strong>diacrónicos con señal interna</strong><p>{pct(any_internal,total)}% de las hipótesis de máquina tienen alguna reatestiguación interna en Steffel.</p></article><article class="pagecard"><span>{recip}/{total}</span><strong>apoyo interno recíproco</strong><p>{pct(recip,total)}% tienen además una señal alemana recíproca. No es una tasa de validación.</p></article></div><div class="callout">Los {s['residual_de_rar_span_candidates_low_machine']} segmentos residuales de baja confianza se conservan aparte y <strong>no se presentan como palabras rarámuri confirmadas</strong>. Toda esta capa mantiene revisión humana = 0.</div><p class="small"><a href="research.html">Abrir portal de investigación interna y diacronía ↗</a></p></section>\n'''
        index=index.replace('<section class="grid2" id="fuente">',panel+'<section class="grid2" id="fuente">',1)
    index=index.replace('<p class="small"><strong>Siguiente etapa:</strong> adjudicar <code>data/validation/human_review_queue.json</code>, registrando revisor, competencia, decisión y evidencia. Sólo después deben adoptarse lecturas críticas, normalizaciones o correspondencias diacrónicas.</p>','<p class="small"><strong>Siguiente etapa de validación:</strong> adjudicar <code>data/validation/human_review_queue.json</code>. En paralelo, las capas documentales no adjudicativas pueden seguir creciendo: concordancia interna, variantes, estadística y contexto diacrónico, siempre sin activar banderas humanas.</p>')
    (PUBLIC/'index.html').write_text(index,encoding='utf-8')

    def find_sem(head):
        for x in sem:
            if x['modern']['headword'].casefold()==head.casefold(): return x
        return None
    def find_con(form):
        for x in con:
            if x['rar_de']['form_diplomatic'].casefold()==form.casefold() and x['relation']['reciprocal_german_support']: return x
        return None
    examples=[]
    a=find_con('Acáca')
    if a: examples.append(('Acáca',a['rar_de']['german_gloss_local'],a['de_rar']['headword_diplomatic'],'Concordancia interna recíproca del mismo Steffel.'))
    c=find_sem('Cuná')
    if c: examples.append((c['historical']['matched_component'],c['historical']['german_gloss_local'],c['modern']['translation_raw'],'Forma histórica y moderna convergen de manera aparente; la capa no adjudica identidad semántica.'))
    b=find_sem('Burá')
    if b: examples.append((b['historical']['matched_component'],b['historical']['german_gloss_local'],b['modern']['translation_raw'],'El apoyo interno fortalece la lectura histórica, pero la divergencia moderna no se etiqueta automáticamente como cambio semántico.'))
    cards=''.join(f'<article class="pagecard"><span>{html.escape(str(form))}</span><strong>{html.escape(str(left))} ↔ {html.escape(str(right))}</strong><p>{html.escape(note)}</p></article>' for form,left,right,note in examples)
    research=f'''<!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Investigación interna — Rarámuri Histórico Digital</title><meta name="description" content="Concordancia interna, variantes, estadística grafémica y contexto diacrónico computacional del Corpus Steffel 1791/1809."><link rel="stylesheet" href="styles.css"></head><body><header class="top"><div class="wrap nav"><div class="brand">Rarámuri Histórico Digital</div><div class="links"><a href="index.html">Corpus</a><a href="#concordancia">Concordancia</a><a href="#diacronia">Diacronía</a><a href="#variantes">Variantes</a><a href="https://github.com/fersandovalgtz/raramuri-historico">GitHub</a></div></div></header><main class="wrap"><section class="hero"><div><div class="eyebrow">Investigación documental · sin adjudicación humana</div><h1>Steffel consigo mismo</h1><p>La doble dirección alemán→rarámuri / rarámuri→alemán permite construir una concordancia interna reproducible antes de cualquier interpretación histórica fuerte.</p><span class="status">● {s['internal_concordance_candidates']} concordancias candidatas · {s['internal_reciprocal_german_support_candidates']} con apoyo recíproco · revisión humana 0</span></div><aside class="source-card"><span class="source-kicker">Regla científica</span><strong>Señal computacional ≠ validación</strong><span>La evidencia diplomática permanece intacta.</span><span>No se automatizan cognación, identidad semántica ni continuidad histórica.</span></aside></section><section class="metrics"><div class="metric"><strong>{s['rar_de_unique_graphic_keys']}</strong><span>claves gráficas RAR–DE únicas</span></div><div class="metric"><strong>{s['de_rar_inventory_guided_attestations']}</strong><span>atestiguaciones DE–RAR guiadas</span></div><div class="metric"><strong>{s['internal_reciprocal_german_support_candidates']}</strong><span>apoyos alemanes recíprocos</span></div><div class="metric"><strong>0</strong><span>relaciones humanamente validadas</span></div></section><section class="panel" id="concordancia"><h2>Concordancia interna bidireccional</h2><p><strong>{s['rar_de_records_attested_inside_de_rar']}/{rar} ({pct(s['rar_de_records_attested_inside_de_rar'],rar)}%)</strong> de los registros activos RAR–DE tienen alguna reatestiguación exacta guiada dentro de DE–RAR. A la inversa, <strong>{s['de_rar_records_with_inventory_guided_attestations']}/{de} ({pct(s['de_rar_records_with_inventory_guided_attestations'],de)}%)</strong> de los artículos DE–RAR contienen al menos una forma del inventario RAR–DE.</p><div class="callout">Las {s['de_rar_inventory_guided_attestations']} coincidencias son atestiguaciones documentales candidatas, no {s['de_rar_inventory_guided_attestations']} lexemas validados. Los {s['residual_de_rar_span_candidates_low_machine']} segmentos residuales se mantienen como baja confianza y fuera de la concordancia.</div></section><section class="panel" id="diacronia"><h2>Contexto para las 298 hipótesis diacrónicas</h2><div class="pagegrid"><article class="pagecard"><span>{recip}</span><strong>apoyo interno recíproco</strong><p>{pct(recip,total)}% de la cola diacrónica tiene una señal documental fuerte dentro del propio Steffel.</p></article><article class="pagecard"><span>{semc.get('internal_form_attestation_only',0)}</span><strong>atestiguación interna</strong><p>La forma reaparece en DE–RAR, pero sin apoyo alemán recíproco detectado.</p></article><article class="pagecard"><span>{semc.get('cross_corpus_context_only',0)}</span><strong>sólo contexto entre corpus</strong><p>No se detectó reatestiguación interna bajo este método conservador.</p></article></div><p class="small">No se calcula similitud semántica alemán↔español. Las glosas se presentan lado a lado para una futura evaluación especializada.</p></section><section class="panel"><h2>Casos que muestran por qué importa</h2><div class="pagegrid">{cards}</div></section><section class="grid2" id="variantes"><div class="panel"><h2>Variantes históricas</h2><p><strong>{s['explicit_source_variant_groups']}</strong> grupos están explícitamente marcados en la fuente mediante separadores como <em>oder</em>. Otros <strong>{s['normalized_graphic_collision_groups']}</strong> grupos sólo colisionan bajo normalización gráfica conservadora y no se llaman variantes lingüísticas automáticamente.</p></div><div class="panel"><h2>Grafemática descriptiva</h2><p>La capa RAR–DE contiene <strong>{s['rar_de_component_attestations']}</strong> componentes y <strong>{s['rar_de_unique_surface_forms']}</strong> formas superficiales. `graphemic_statistics.json` preserva frecuencia de caracteres y diacríticos como estadística de cadenas diplomáticas, sin interpretación fonológica.</p></div></section><section class="panel"><h2>Datos reproducibles</h2><p class="small"><code>data/research/internal_concordance.json/.csv</code> · <code>diachronic_semantic_context_queue.json/.csv</code> · <code>historical_variant_index.json</code> · <code>graphemic_statistics.json</code> · <code>corpus_research_statistics.json</code> · <code>RESEARCH_SNAPSHOT.md</code>.</p><div class="callout"><strong>Estado epistemológico:</strong> revisión humana de estas relaciones = 0. Las capas son útiles para formular hipótesis, ordenar evidencia y medir cobertura, no para sustituir la adjudicación filológica o lingüística independiente.</div></section></main><footer class="wrap footer">Rarámuri Histórico Digital · Corpus Steffel 1791/1809 · investigación computacional reproducible · 2026</footer></body></html>'''
    (PUBLIC/'research.html').write_text(research,encoding='utf-8')

if __name__=='__main__': main()
